use crate::aap::caps::http_client;

struct Node;

/// The node's `with` clause: the only hosts this body may ask for. A request
/// outside the handle's allowlist traps at the boundary, so the body checks
/// first and records such URLs as failures instead of letting one bad entry
/// abort the whole batch.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host of an http(s) URL conservatively. Anything ambiguous
/// (control characters, whitespace, backslashes, percent-escapes, IPv6
/// literals) yields `None`, so it is refused rather than interpreted.
fn host_of(url: &str) -> Option<&str> {
    if url.bytes().any(|b| b <= 0x20 || b == 0x7f || b == b'\\' || b == b'%') {
        return None;
    }
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    let after_userinfo = authority.rsplit('@').next()?;
    if after_userinfo.starts_with('[') {
        return None;
    }
    let host = after_userinfo.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn allowed(url: &str) -> bool {
    match host_of(url) {
        Some(host) => ALLOWED_HOSTS.iter().any(|a| a.eq_ignore_ascii_case(host)),
        None => false,
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // The "record last-input in the shared store" request is not implemented:
        // this node's `with` clause grants only `aap:caps/http-client`, and the
        // state interfaces are not in its world. Writing to a store would exceed
        // the granted authority, so the output is unchanged and no state import
        // is declared.

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "url outside declared host allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
